--- a/internal/diff/parser.go
+++ b/internal/diff/parser.go
@@ -1,329 +1,404 @@
 package diff

 import (
 	"fmt"
 	"regexp"
 	"strconv"
 	"strings"
 )

 type LineKind int

 const (
 	KindMeta LineKind = iota
 	KindHeader
 	KindHunk
 	KindAdd
 	KindDel
 	KindCtx
 )

 type Line struct {
 	Text   string
 	Kind   LineKind
 	OldNum int
 	NewNum int
+	// NoNewline=true when the original diff had a `\ No newline at end of file`
+	// marker immediately following this line. Per unified-diff spec the marker
+	// applies to the side(s) implied by the line's prefix: ' ' = both, '-' =
+	// old, '+' = new. Lost markers cause `git apply --cached` to reject the
+	// patch because context lengths no longer match HEAD.
+	NoNewline bool
 }

 type RowKind int

 const (
 	RowCtx RowKind = iota
 	RowMod
 	RowDel
 	RowAdd
 	RowHunk
 	RowMeta
 )

 type AlignedRow struct {
 	Kind    RowKind
 	OldNum  int
 	NewNum  int
 	OldText string
 	NewText string
 	// Source indices into the input lines slice. -1 if N/A. Used to map a
 	// split-view row back to the underlying unified line(s) for staging.
 	OldSrcIdx int
 	NewSrcIdx int
 }

 var hunkRe = regexp.MustCompile(`^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@`)

 // ComputeStagedIndices returns the set of indices in `combined` whose line is
 // also present in `staged`. Both inputs are filtered (ctx/del/add only) and
 // share the same HEAD reference. Del lines are matched by oldNum; add lines by
 // (anchor=previous ctx/del oldNum, content) — duplicates are matched in order.
 func ComputeStagedIndices(combined, staged []Line) map[int]bool {
 	out := map[int]bool{}
 	if len(combined) == 0 || len(staged) == 0 {
 		return out
 	}

 	stagedDels := map[int]bool{}
 	type addKey struct {
 		anchor  int
 		content string
 	}
 	stagedAddCount := map[addKey]int{}
 	anchor := 0
 	for _, l := range staged {
 		switch l.Kind {
 		case KindCtx:
 			anchor = l.OldNum
 		case KindDel:
 			stagedDels[l.OldNum] = true
 			anchor = l.OldNum
 		case KindAdd:
 			content := strings.TrimPrefix(l.Text, "+")
 			stagedAddCount[addKey{anchor, content}]++
 		}
 	}

 	anchor = 0
 	for i, l := range combined {
 		switch l.Kind {
 		case KindCtx:
 			anchor = l.OldNum
 		case KindDel:
 			if stagedDels[l.OldNum] {
 				out[i] = true
 			}
 			anchor = l.OldNum
 		case KindAdd:
 			content := strings.TrimPrefix(l.Text, "+")
 			key := addKey{anchor, content}
 			if stagedAddCount[key] > 0 {
 				stagedAddCount[key]--
 				out[i] = true
 			}
 		}
 	}
 	return out
 }

 // BuildPartialPatch builds a unified-diff patch suitable for `git apply --cached`.
 // Only the changes in `include` (a set of indices into `combined`) appear as
 // actual del/add operations. Unselected dels become context (HEAD-and-index
 // still has them); unselected adds are omitted (neither HEAD nor index has them).
 // Returns "" if there's nothing to stage, or if the file kind isn't supported
 // for patch-based staging (e.g., untracked — handle those via git add directly).
 func BuildPartialPatch(path string, combined []Line, include map[int]bool) string {
 	if len(include) == 0 {
 		return ""
 	}
-	var body strings.Builder
+	type bodyEntry struct {
+		ch     byte // ' ', '-', '+'
+		text   string
+		srcIdx int // index into combined; used to look up NoNewline for trailing markers
+	}
+	var entries []bodyEntry
 	oldCount, newCount := 0, 0
 	any := false
 	for i, l := range combined {
 		switch l.Kind {
 		case KindCtx:
 			txt := strings.TrimPrefix(l.Text, " ")
-			body.WriteString(" " + txt + "\n")
+			entries = append(entries, bodyEntry{' ', txt, i})
 			oldCount++
 			newCount++
 		case KindDel:
 			txt := strings.TrimPrefix(l.Text, "-")
 			if include[i] {
-				body.WriteString("-" + txt + "\n")
+				entries = append(entries, bodyEntry{'-', txt, i})
 				oldCount++
 				any = true
 			} else {
 				// Unselected del → context: HEAD has it, post-apply index also has it.
-				body.WriteString(" " + txt + "\n")
+				entries = append(entries, bodyEntry{' ', txt, i})
 				oldCount++
 				newCount++
 			}
 		case KindAdd:
 			txt := strings.TrimPrefix(l.Text, "+")
 			if include[i] {
-				body.WriteString("+" + txt + "\n")
+				entries = append(entries, bodyEntry{'+', txt, i})
 				newCount++
 				any = true
 			}
 			// Unselected adds are omitted entirely.
 		}
 	}
 	if !any {
 		return ""
 	}
+
+	// Locate the last entry on each side so we can place `\ No newline …`
+	// markers correctly. The patch's old side is HEAD verbatim, so its trailing
+	// state must match HEAD's; the new side reflects the post-patch index.
+	oldLast, newLast := -1, -1
+	for i := len(entries) - 1; i >= 0; i-- {
+		if oldLast < 0 && (entries[i].ch == ' ' || entries[i].ch == '-') {
+			oldLast = i
+		}
+		if newLast < 0 && (entries[i].ch == ' ' || entries[i].ch == '+') {
+			newLast = i
+		}
+		if oldLast >= 0 && newLast >= 0 {
+			break
+		}
+	}
+	// HEAD lacks trailing newline iff the file's last old-side line in `combined`
+	// (last KindCtx or KindDel) carried the marker.
+	headNoNewline := false
+	for i := len(combined) - 1; i >= 0; i-- {
+		if combined[i].Kind == KindCtx || combined[i].Kind == KindDel {
+			headNoNewline = combined[i].NoNewline
+			break
+		}
+	}
+	// Post-patch new side lacks trailing newline iff the source line of the
+	// chosen new-side-last carried a marker. For a ctx/del-as-ctx that's HEAD's
+	// state for that line; for an included add it's the working tree's state.
+	postNoNewline := false
+	if newLast >= 0 {
+		postNoNewline = combined[entries[newLast].srcIdx].NoNewline
+	}
+
+	const marker = "\\ No newline at end of file\n"
 	var buf strings.Builder
 	buf.WriteString("diff --git a/" + path + " b/" + path + "\n")
 	buf.WriteString("--- a/" + path + "\n")
 	buf.WriteString("+++ b/" + path + "\n")
 	fmt.Fprintf(&buf, "@@ -1,%d +1,%d @@\n", oldCount, newCount)
-	buf.WriteString(body.String())
+	for i, e := range entries {
+		buf.WriteByte(e.ch)
+		buf.WriteString(e.text)
+		buf.WriteByte('\n')
+		// Marker placement rules — a marker after a ' ' line applies to both
+		// sides, after '-' to old only, after '+' to new only.
+		switch {
+		case i == oldLast && i == newLast:
+			if headNoNewline || postNoNewline {
+				buf.WriteString(marker)
+			}
+		case i == oldLast:
+			if headNoNewline {
+				buf.WriteString(marker)
+			}
+		case i == newLast:
+			if postNoNewline {
+				buf.WriteString(marker)
+			}
+		}
+	}
 	return buf.String()
 }

 func Parse(text string) []Line {
 	var out []Line
 	oldNum, newNum := 0, 0
 	inHunk := false
 	lines := strings.Split(text, "\n")
 	// Drop the trailing empty element produced by strings.Split when the text
 	// ends with "\n" — otherwise it gets classified as a phantom ctx line and
 	// throws hunk counts off by one, breaking `git apply --cached`.
 	if len(lines) > 0 && lines[len(lines)-1] == "" {
 		lines = lines[:len(lines)-1]
 	}
 	for _, line := range lines {
 		if strings.HasPrefix(line, "@@") {
 			if m := hunkRe.FindStringSubmatch(line); m != nil {
 				oldNum, _ = strconv.Atoi(m[1])
 				newNum, _ = strconv.Atoi(m[2])
 				inHunk = true
 			}
 			out = append(out, Line{Text: line, Kind: KindHunk})
 			continue
 		}
 		if strings.HasPrefix(line, "+++") || strings.HasPrefix(line, "---") {
 			out = append(out, Line{Text: line, Kind: KindHeader})
 			inHunk = false
 			continue
 		}
+		// Inside a hunk, `\ No newline at end of file` is a marker that attaches
+		// to the previously-emitted content line — never a standalone entry.
+		// Dropping it (or treating it as Meta) loses information BuildPartialPatch
+		// needs to keep the patch consistent with HEAD's trailing-newline state.
+		if inHunk && strings.HasPrefix(line, `\`) {
+			if len(out) > 0 {
+				out[len(out)-1].NoNewline = true
+			}
+			continue
+		}
 		if isMeta(line) {
 			out = append(out, Line{Text: line, Kind: KindMeta})
 			inHunk = false
 			continue
 		}
 		if !inHunk {
 			out = append(out, Line{Text: line, Kind: KindMeta})
 			continue
 		}
 		if strings.HasPrefix(line, "+") {
 			out = append(out, Line{Text: line, Kind: KindAdd, NewNum: newNum})
 			newNum++
 		} else if strings.HasPrefix(line, "-") {
 			out = append(out, Line{Text: line, Kind: KindDel, OldNum: oldNum})
 			oldNum++
 		} else {
 			out = append(out, Line{
 				Text:   line,
 				Kind:   KindCtx,
 				OldNum: oldNum,
 				NewNum: newNum,
 			})
 			oldNum++
 			newNum++
 		}
 	}
 	return out
 }

 func isMeta(s string) bool {
 	switch {
 	case strings.HasPrefix(s, "diff "),
 		strings.HasPrefix(s, "index "),
 		strings.HasPrefix(s, "new file"),
 		strings.HasPrefix(s, "deleted file"),
 		strings.HasPrefix(s, "similarity "),
 		strings.HasPrefix(s, "rename "),
 		strings.HasPrefix(s, "Binary "),
 		strings.HasPrefix(s, `\`): // "\ No newline at end of file" marker
 		return true
 	}
 	return false
 }

 // Align builds the side-by-side aligned rows from a unified Line slice. The
 // indices stored in OldSrcIdx/NewSrcIdx point back into the input slice — pass
 // the SAME slice the caller intends to use as canonical (e.g. filtered).
 func Align(lines []Line) []AlignedRow {
 	var out []AlignedRow
 	i := 0
 	for i < len(lines) {
 		line := lines[i]
 		if line.Kind == KindCtx {
 			txt := strings.TrimPrefix(line.Text, " ")
 			out = append(out, AlignedRow{
 				Kind:      RowCtx,
 				OldNum:    line.OldNum,
 				NewNum:    line.NewNum,
 				OldText:   txt,
 				NewText:   txt,
 				OldSrcIdx: i,
 				NewSrcIdx: i,
 			})
 			i++
 			continue
 		}
 		if line.Kind == KindDel || line.Kind == KindAdd {
 			type idxLine struct {
 				line Line
 				idx  int
 			}
 			var dels, adds []idxLine
 			for i < len(lines) && lines[i].Kind == KindDel {
 				dels = append(dels, idxLine{lines[i], i})
 				i++
 			}
 			for i < len(lines) && lines[i].Kind == KindAdd {
 				adds = append(adds, idxLine{lines[i], i})
 				i++
 			}
 			max := len(dels)
 			if len(adds) > max {
 				max = len(adds)
 			}
 			for j := 0; j < max; j++ {
 				var d, a *idxLine
 				if j < len(dels) {
 					d = &dels[j]
 				}
 				if j < len(adds) {
 					a = &adds[j]
 				}
 				switch {
 				case d != nil && a != nil:
 					out = append(out, AlignedRow{
 						Kind:      RowMod,
 						OldNum:    d.line.OldNum,
 						NewNum:    a.line.NewNum,
 						OldText:   strings.TrimPrefix(d.line.Text, "-"),
 						NewText:   strings.TrimPrefix(a.line.Text, "+"),
 						OldSrcIdx: d.idx,
 						NewSrcIdx: a.idx,
 					})
 				case d != nil:
 					out = append(out, AlignedRow{
 						Kind:      RowDel,
 						OldNum:    d.line.OldNum,
 						OldText:   strings.TrimPrefix(d.line.Text, "-"),
 						OldSrcIdx: d.idx,
 						NewSrcIdx: -1,
 					})
 				case a != nil:
 					out = append(out, AlignedRow{
 						Kind:      RowAdd,
 						NewNum:    a.line.NewNum,
 						NewText:   strings.TrimPrefix(a.line.Text, "+"),
 						OldSrcIdx: -1,
 						NewSrcIdx: a.idx,
 					})
 				}
 			}
 			continue
 		}
 		if line.Kind == KindHunk {
 			out = append(out, AlignedRow{
 				Kind:      RowHunk,
 				OldText:   line.Text,
 				NewText:   line.Text,
 				OldSrcIdx: -1,
 				NewSrcIdx: -1,
 			})
 			i++
 			continue
 		}
 		out = append(out, AlignedRow{
 			Kind:      RowMeta,
 			OldText:   line.Text,
 			NewText:   line.Text,
 			OldSrcIdx: -1,
 			NewSrcIdx: -1,
 		})
 		i++
 	}
 	return out
 }

