 // loadDiffPair runs git diff HEAD and git diff --cached HEAD in parallel and
 // computes the staged-line indices. Shared by loadDiffCmd (UI refresh) and
 // stageFileCmd (auto-decide stage vs unstage).
 func loadDiffPair(source git.Source, file git.ChangedFile) (combined []diff.Line, aligned []diff.AlignedRow, stagedIdx map[int]bool, err error) {
 	var combinedText, stagedText string
 	var combinedErr error
 	var wg sync.WaitGroup
 	wg.Add(2)
 	go func() {
 		defer wg.Done()
 		combinedText, combinedErr = git.LoadDiff(source, file)
 	}()
 	go func() {
 		defer wg.Done()
 		stagedText, _ = git.LoadStagedDiff(source, file)
 	}()
 	wg.Wait()
 	if combinedErr != nil {
 		return nil, nil, nil, combinedErr
 	}
 	combined = filterContentLines(diff.Parse(combinedText))
 	aligned = diff.Align(combined)
 	if stagedText != "" {
 		stagedLines := filterContentLines(diff.Parse(stagedText))
 		stagedIdx = diff.ComputeStagedIndices(combined, stagedLines)
 	}
 	return combined, aligned, stagedIdx, nil
 }

