 	return func() tea.Msg {
 		files, err := git.LoadChangedFiles(source)
 		return filesLoadedMsg{files: files, err: err}
 	}
 }

 func loadDiffCmd(source git.Source, file git.ChangedFile) tea.Cmd {
 	return func() tea.Msg {
 		combined, aligned, stagedIdx, err := loadDiffPair(source, file)
 		if err != nil {
