-			aligned: aligned,
-			staged:  stagedIdx,
+			path:       file.Path,
+			unified:    combined,
+			aligned:    aligned,
+			current:    current,
+			currentIdx: currentIdx,
+			staged:     stagedIdx,
 		}
 	}
 }

+// filterCurrentView produces the post-change file view: ctx + add lines only.
+// The parallel index slice maps each filtered row back to its position in the
+// unified slice so staging and other unified-indexed operations still work.
+func filterCurrentView(in []diff.Line) (out []diff.Line, idx []int) {
+	out = make([]diff.Line, 0, len(in))
+	idx = make([]int, 0, len(in))
+	for i, l := range in {
+		if l.Kind == diff.KindDel {
+			continue
+		}
+		out = append(out, l)
