 // stageFileCmd runs `git add` or `git restore --staged` for an entire file.
 // Auto-decides direction: if any line is already staged → unstage; else stage.
 func stageFileCmd(source git.Source, file git.ChangedFile) tea.Cmd {
 	return func() tea.Msg {
 		combined, _, stagedIdx, err := loadDiffPair(source, file)
 		if err != nil {
 			return stagingDoneMsg{path: file.Path, err: err}
 		}
 		anyStaged := false
 		for i, l := range combined {
 			if l.Kind != diff.KindAdd && l.Kind != diff.KindDel {
 				continue
 			}
 			if stagedIdx[i] {
 				anyStaged = true
 				break
 			}
 		}
 		var opErr error
 		if anyStaged {
 			opErr = git.UnstageFile(file.Path)
 		} else {
 			opErr = git.StageFile(file.Path)
 		}
 		return stagingDoneMsg{path: file.Path, err: opErr}
 	}
 }

 // resetAndApplyCmd resets the file's index to HEAD then applies the patch
 // representing the desired staged set. Doing it this way guarantees the
 // patch's base (HEAD) always matches the index, so `git apply --cached` never
 // fails because of context drift from a previous partial stage.
 func resetAndApplyCmd(file git.ChangedFile, patch string) tea.Cmd {
 	return func() tea.Msg {
 		_ = git.UnstageFile(file.Path) // best-effort; no-op if nothing was staged
 		if patch == "" {
 			return stagingDoneMsg{path: file.Path}
 		}
 		if err := git.ApplyPatchToIndex(patch); err != nil {
 			return stagingDoneMsg{path: file.Path, err: err}
 		}
 		return stagingDoneMsg{path: file.Path}
 	}
 }

 // filterContentLines drops meta/header/hunk lines so the remaining slice
 // holds only ctx/del/add — what we cache and render.
 func filterContentLines(in []diff.Line) []diff.Line {
 	out := make([]diff.Line, 0, len(in))
 	for _, l := range in {
 		if l.Kind == diff.KindMeta || l.Kind == diff.KindHeader || l.Kind == diff.KindHunk {
 			continue
 		}
 		out = append(out, l)
 	}
 	return out
 }

 // inTmux reports whether eleview is running inside a tmux session.
 // Used to decide between display-popup (in-tmux) and a plain child process.
 func inTmux() bool { return os.Getenv("TMUX") != "" }

 // contentFramePopupArgs returns tmux display-popup args that position the
 // popup precisely inside the content pane's text area.
 //
 // Layout from top:
 //   - rows 1..3      header (rounded border = 3 rows)
 //   - row  4         content pane top border
 //   - row  5         first content row
 //
 // Layout from left:
 //   - col 1..treeW           tree pane
 //   - col treeW+1            content pane border-left
 //   - col treeW+2            content pane padding-left
 //   - col treeW+3..(end-2)   content text
 func (m Model) contentFramePopupArgs() []string {
 	x := m.treePanelWidth() + 3
 	y := 5
 	w := m.diffPanelWidth() - 4
 	h := m.paneInnerHeight()
 	if w < 1 {
 		w = 1
 	}
 	if h < 1 {
 		h = 1
 	}
 	return []string{
 		"display-popup", "-B", "-E",
 		"-x", fmt.Sprintf("%d", x),
 		"-y", fmt.Sprintf("%d", y),
 		"-w", fmt.Sprintf("%d", w),
 		"-h", fmt.Sprintf("%d", h),
 	}
 }

 func centeredPopupArgs(widthPct, heightPct int) []string {
 	return []string{
 		"display-popup", "-B", "-E",
 		"-w", fmt.Sprintf("%d%%", widthPct),
 		"-h", fmt.Sprintf("%d%%", heightPct),
 	}
 }

