--- /dev/null
+++ b/internal/ui/finder.go
@@ -0,0 +1,289 @@
+package ui
+
+import (
+	"fmt"
+	"strings"
+
+	"eleview/internal/git"
+
+	"github.com/charmbracelet/bubbles/textinput"
+	tea "github.com/charmbracelet/bubbletea"
+	"github.com/charmbracelet/lipgloss"
+	"github.com/charmbracelet/x/ansi"
+)
+
+// newFinderModal creates an empty finder modal. matches are computed on every
+// keystroke against the model's current file list — see (Model).refreshFinder.
+func newFinderModal() *finderModal {
+	ti := textinput.New()
+	ti.Placeholder = "search files (space-separated terms — \"con task\" matches \"Controllers/Task.ts\")"
+	ti.Prompt = "❯ "
+	ti.CharLimit = 200
+	ti.Focus()
+	return &finderModal{
+		input:  ti,
+		cursor: 0,
+	}
+}
+
+// updateFinder routes all input while the file picker is open.
+func (m Model) updateFinder(msg tea.Msg) (tea.Model, tea.Cmd) {
+	keyMsg, isKey := msg.(tea.KeyMsg)
+	if !isKey {
+		// Cursor blink ticks for the textinput.
+		var cmd tea.Cmd
+		m.finder.input, cmd = m.finder.input.Update(msg)
+		return m, cmd
+	}
+	switch keyMsg.String() {
+	case "ctrl+c":
+		return m, tea.Quit
+	case "esc":
+		m.finder = nil
+		return m, nil
+	case "up", "ctrl+p":
+		if m.finder.cursor > 0 {
+			m.finder.cursor--
+		}
+		return m, nil
+	case "down", "ctrl+n":
+		if m.finder.cursor < len(m.finder.matches)-1 {
+			m.finder.cursor++
+		}
+		return m, nil
+	case "enter":
+		if m.finder.cursor < 0 || m.finder.cursor >= len(m.finder.matches) {
+			return m, nil
+		}
+		fileIdx := m.finder.matches[m.finder.cursor]
+		if fileIdx < 0 || fileIdx >= len(m.files) {
+			return m, nil
+		}
+		picked := m.files[fileIdx]
+		m.finder = nil
+		// Move cursor in the tree to the picked file so the tree pane stays
+		// in sync with the content pane after the picker closes.
+		for i, f := range m.flat {
+			if file, ok := f.Node.(interface{ Path() string }); ok && file.Path() == picked.Path {
+				m.cursor = i
+				break
+			}
+		}
+		m.selectedPath = picked.Path
+		m.contentCursor = 0
+		m.contentScroll = 0
+		m.selectionAnchor = -1
+		m.focus = FocusContent
+		if _, ok := m.cache[picked.Path]; ok {
+			return m, nil
+		}
+		if m.loadingDiff[picked.Path] {
+			return m, nil
+		}
+		m.loadingDiff[picked.Path] = true
+		return m, loadDiffCmd(m.source, picked)
+	}
