+
+// refreshFinder rebuilds the match list from the current query. Multi-term
+// fuzzy match: split the query by spaces, lowercase, and require every term to
+// appear in the path (also lowercased). Order doesn't matter — "con task"
+// matches "Controllers/Task.ts" because both "con" and "task" appear in the
+// path.
+//
+// Ranking: sum of the earliest start-position of each term in the path; lower
+// is better. Ties broken by shorter path.
+func (m *Model) refreshFinder() {
+	if m.finder == nil {
+		return
+	}
+	q := strings.ToLower(strings.TrimSpace(m.finder.input.Value()))
+	terms := strings.Fields(q)
