+		positions := make([]int, 0, len(terms))
+		for _, t := range terms {
+			pos := strings.Index(path, t)
+			if pos < 0 {
+				matched = false
+				break
+			}
+			score += pos
+			positions = append(positions, pos)
+		}
+		if !matched {
+			continue
+		}
+		score = score*1000 + len(path) // tie-break on path length
+		hits = append(hits, scored{idx: i, score: score, positions: positions})
+	}
+	if q != "" {
+		// Stable-ish sort by score ascending.
+		for i := 1; i < len(hits); i++ {
+			for j := i; j > 0 && hits[j-1].score > hits[j].score; j-- {
+				hits[j-1], hits[j] = hits[j], hits[j-1]
+			}
+		}
+	}
+	m.finder.matches = make([]int, len(hits))
+	m.finder.positions = make([][]int, len(hits))
+	for i, h := range hits {
+		m.finder.matches[i] = h.idx
+		m.finder.positions[i] = h.positions
+	}
+	if m.finder.cursor >= len(m.finder.matches) {
+		m.finder.cursor = len(m.finder.matches) - 1
+	}
+	if m.finder.cursor < 0 {
+		m.finder.cursor = 0
+	}
+}
+
+// renderFinder builds the picker overlay. Sized generously because paths can
+// be long.
+func (m Model) renderFinder() string {
+	outerW := m.width * 4 / 5
+	if outerW > 140 {
+		outerW = 140
+	}
+	if outerW < 50 {
+		outerW = 50
+	}
+	bodyH := m.height - 12
+	if bodyH > 22 {
+		bodyH = 22
+	}
+	if bodyH < 6 {
+		bodyH = 6
+	}
+	rowW := outerW - 6 // border + padding
+	if rowW < 1 {
+		rowW = 1
+	}
+
+	var lines []string
+	lines = append(lines, AppNameStyle.Render(fmt.Sprintf("Find file (%d/%d)", len(m.finder.matches), len(m.files))))
+	lines = append(lines, m.finder.input.View())
+	lines = append(lines, DimStyle.Render(strings.Repeat("─", rowW)))
+
+	// Match list with a window centered on the cursor.
+	if len(m.finder.matches) == 0 {
+		lines = append(lines, DimStyle.Render("  no matches"))
+		for i := 0; i < bodyH-1; i++ {
+			lines = append(lines, "")
+		}
+	} else {
+		half := bodyH / 2
+		start := m.finder.cursor - half
+		if start < 0 {
+			start = 0
+		}
+		end := start + bodyH
+		if end > len(m.finder.matches) {
+			end = len(m.finder.matches)
+			start = end - bodyH
+			if start < 0 {
+				start = 0
+			}
+		}
+		shown := 0
+		for i := start; i < end; i++ {
+			fileIdx := m.finder.matches[i]
+			f := m.files[fileIdx]
+			lines = append(lines, m.renderFinderRow(f, i == m.finder.cursor, rowW))
+			shown++
+		}
+		for shown < bodyH {
+			lines = append(lines, "")
+			shown++
+		}
+	}
+	lines = append(lines, DimStyle.Render(
+		HotkeyStyle.Render("↑↓")+" navigate · "+
+			HotkeyStyle.Render("enter")+" open · "+
+			HotkeyStyle.Render("esc")+" close"))
+
+	return lipgloss.NewStyle().
+		Border(lipgloss.RoundedBorder()).
+		BorderForeground(colorPrimary).
+		Padding(1, 2).
+		Width(outerW - 2).
+		Render(strings.Join(lines, "\n"))
+}
+
+// renderFinderRow mirrors the visual treatment of renderTreeRow's file branch
+// — same status-badge colors, same staged/comment cues — so the picker reads
+// as "the tree, but filtered" rather than a different widget.
+func (m Model) renderFinderRow(f git.ChangedFile, isCursor bool, width int) string {
+	statusChar := string(f.Status)
+	fullyStaged := f.FullyStaged()
+	hasThreads := m.FileHasThreads(f.Path)
+
+	if isCursor {
+		bgOnly := lipgloss.NewStyle().Background(cursorBg)
+		marker := lipgloss.NewStyle().Background(cursorBg).Foreground(colorAccent).Bold(true).Render("▶ ")
+		badge := StatusStyle(f.Status).Background(cursorBg).Render(statusChar)
+		pathStyle := bgOnly
+		if fullyStaged {
+			pathStyle = FileStagedStyle.Background(cursorBg)
+		}
+		body := marker + badge + bgOnly.Render("  ") + pathStyle.Render(f.Path)
+		// Right-aligned comment marker, like the tree.
+		rightMarker := ""
+		rightW := 0
+		if hasThreads {
+			rightMarker = lipgloss.NewStyle().Background(cursorBg).Foreground(commentBg).Render("●")
+			rightW = 1
+		}
+		if ansi.StringWidth(body)+rightW > width {
+			return ansi.Truncate(body, width, "")
+		}
+		if w := ansi.StringWidth(body); w+rightW < width {
+			body += bgOnly.Render(strings.Repeat(" ", width-w-rightW))
+		}
+		body += rightMarker
+		return body
+	}
+
+	badge := StatusStyle(f.Status).Render(statusChar)
+	name := f.Path
+	switch {
+	case fullyStaged:
+		name = FileStagedStyle.Render(name)
+	default:
+		name = TextStyle.Render(name)
+	}
+	body := "  " + badge + "  " + name
+	if hasThreads {
+		marker := MarkerStyle.Render("●")
+		bodyW := ansi.StringWidth(body)
+		if bodyW+2 <= width {
+			body += strings.Repeat(" ", width-bodyW-1) + marker
+			return body
+		}
+	}
+	if w := ansi.StringWidth(body); w > width {
+		return ansi.Truncate(body, width, "")
+	}
+	return body
+}

