 // navigateToPendingLine scans the active cache for a row whose working-tree
 // line number matches the pending target and parks the cursor there.
 func (m *Model) navigateToPendingLine() {
 	if m.pendingNavLine == 0 || m.selectedPath == "" {
 		return
 	}
 	target := m.pendingNavLine
 	m.pendingNavLine = 0
 	cached, ok := m.cache[m.selectedPath]
 	if !ok {
 		return
 	}
 	if m.splitView {
 		for i, r := range cached.split {
 			if r.NewNum == target {
 				m.contentCursor = i
 				m.ensureCursorVisible()
 				return
 			}
 		}
 		return
 	}
 	for i, l := range cached.unified {
 		if l.NewNum == target {
 			m.contentCursor = i
