 		} else {
 			c = exec.Command("nvim", m.selectedPath)
 		}
 		return m, tea.ExecProcess(c, func(err error) tea.Msg {
 			return externalProcessDoneMsg{err: err}
 		})
 	case "tab":
 		m.splitView = !m.splitView
 		m.contentCursor = 0
 		m.contentScroll = 0
 		m.selectionAnchor = -1
 		return m, nil
 	case "shift+up":
 		if m.selectionAnchor < 0 {
 			m.selectionAnchor = m.contentCursor
 		}
 		if m.contentCursor > 0 {
 			m.contentCursor--
 		}
 	case "shift+down":
 		if m.selectionAnchor < 0 {
 			m.selectionAnchor = m.contentCursor
 		}
 		if m.contentCursor < n-1 {
 			m.contentCursor++
 		}
 	case "up", "k":
 		if m.contentCursor > 0 {
 			m.contentCursor--
 		}
 		m.selectionAnchor = -1
 	case "down", "j":
 		if m.contentCursor < n-1 {
 			m.contentCursor++
 		}
 		m.selectionAnchor = -1
 	case "pgup":
 		m.contentCursor -= h / 2
 		if m.contentCursor < 0 {
 			m.contentCursor = 0
 		}
 		m.selectionAnchor = -1
 	case " ":
 		return m.toggleStaged()
 	case "enter":
 		return m.openOrCreateThread()
 	case "pgdown":
+	case "pgdown", "ctrl+d":
 		m.contentCursor += h / 2
 		if m.contentCursor > n-1 {
 			m.contentCursor = n - 1
 		}
 		m.selectionAnchor = -1
 	case "home":
 		m.contentCursor = 0
 		m.selectionAnchor = -1
 	case "end", "G":
 		m.contentCursor = n - 1
 		m.selectionAnchor = -1
 	}
 	m.ensureCursorVisible()
 	return m, nil
 }

